	/** The sweep may only detach keys from a self-contained positive relation with a value in every key column. */
	private static boolean canSweep(RowState row, SlotPlan left, SlotPlan right, int[] keys) {
		NativeLmdbQuerySource physical = row.source;
		while (physical instanceof SyntheticValueSource synthetic) {
			physical = synthetic.delegate;
		}
		if (physical == null || !physical.hasCanonicalIds() || keys.length == 0 || row.encounterOrderRequired) {
			return false;
		}
		long keyMask = 0L;
		for (int slot : keys) {
			keyMask |= 1L << slot;
		}
		long reads = memoReadMask(right);
		if (reads < 0L || (reads & ~right.producedMask()) != 0L
				|| (reads & left.producedMask()) != keyMask
				|| ((row.boundMask() | row.baseBindingMask) & right.producedMask()) != 0L) {
			return false;
		}
		for (long mask = right.producedMask(); mask != 0L; mask &= mask - 1L) {
			int slot = Long.numberOfTrailingZeros(mask);
			if (row.slots[slot] != UNKNOWN || row.summaryCell(slot) != null) {
				return false;
			}
		}
		return sweepShape(right, keyMask);
	}

	private static boolean sweepShape(SlotPlan plan, long keys) {
		if (plan instanceof UnionPlan union) {
			return sweepShape(union.left, keys) && sweepShape(union.right, keys);
		}
		if (!(plan instanceof PatternPlan pattern) || pattern.range != null || pattern.statementOrder != null
				|| (pattern.producedMask() & keys) != keys) {
			return false;
		}
		for (long mask = keys; mask != 0L; mask &= mask - 1L) {
			int position = pattern.quadPositionOfSlot(Long.numberOfTrailingZeros(mask));
			if (position < 0 || position == TripleIndex.CONTEXT_IDX) {
				return false;
			}
		}
		return true;
	}

	private static boolean usableKey(RowState row, int[] keys) {
		NativeTermAuthority authority = row.termAuthority();
		for (int slot : keys) {
			long id = row.slots[slot];
			if (id == UNKNOWN || id == NULL_CONTEXT_ID || row.summaryCell(slot) != null
					|| (authority != null && authority.kind(id) != NativeIdKind.STORE)) {
				return false;
			}
		}
		return true;
	}

	/**
	 * Each physical index entry can be visited at most once per source/context scan. An initial seek is charged per
	 * source and context; if bound fields are not all in the index prefix, conservatively charge one skip seek per
	 * visited entry. TreeMap bounds key comparisons by the red-black tree height, and the remaining terms pay for
	 * copying each retained key and replay row, including array growth. Saturation rejects unrepresentable budgets.
	 */
	private static SweepBound sweepBound(SlotPlan plan, RowState row, NativeLmdbQuerySource.IndexAccessProfile profile,
			int keyWidth, int replayWidth) {
		long total = maximumSweepRows(plan, profile);
		int height = total == 0L ? 0 : 2 * (Long.SIZE - Long.numberOfLeadingZeros(total));
		return sweepBound(plan, row, profile, keyWidth, replayWidth, height);
	}

	private static long maximumSweepRows(SlotPlan plan, NativeLmdbQuerySource.IndexAccessProfile profile) {
		if (plan instanceof UnionPlan union) {
			return saturatedAdd(maximumSweepRows(union.left, profile), maximumSweepRows(union.right, profile));
		}
		PatternPlan pattern = (PatternPlan) plan;
		long contexts = pattern.contexts.isFixed() ? pattern.contexts.ids.length : 1L;
		return saturatedMultiply(profile.entries(), contexts);
	}

	private static SweepBound sweepBound(SlotPlan plan, RowState row, NativeLmdbQuerySource.IndexAccessProfile profile,
			int keyWidth, int replayWidth, int height) {
		if (plan instanceof UnionPlan union) {
			SweepBound left = sweepBound(union.left, row, profile, keyWidth, replayWidth, height);
			SweepBound right = sweepBound(union.right, row, profile, keyWidth, replayWidth, height);
			return left == null || right == null ? null
					: new SweepBound(saturatedAdd(left.seeks(), right.seeks()),
							saturatedAdd(left.rows(), right.rows()));
		}
		if (!(plan instanceof PatternPlan pattern)) {
			return null;
		}
		long contexts = pattern.contexts.isFixed() ? pattern.contexts.ids.length : 1L;
		long entries = saturatedMultiply(profile.entries(), contexts);
		long seeks = saturatedMultiply(profile.sources(), contexts);
		int bindingMask = 0;
		long subj = pattern.s.lookup(row.slots);
		long pred = pattern.p.lookup(row.slots);
		long obj = pattern.o.lookup(row.slots);
		if (subj > 0L) {
			bindingMask |= 1;
		}
		if (pred > 0L) {
			bindingMask |= 2;
		}
		if (obj > 0L) {
			bindingMask |= 4;
		}
		if (pattern.c.lookup(row.slots) >= 0L || pattern.contexts.isFixed()) {
			bindingMask |= 8;
		}
		int prefix = profile.prefixMask(null, bindingMask);
		if (prefix < 0) {
			return null;
		}
		// Index selection treats zero as bound, while the cursor treats it as an SPO wildcard.
		if (subj == 0L || pred == 0L || obj == 0L || prefix != bindingMask) {
			seeks = saturatedAdd(seeks, entries);
		}
		// The height accounts for all UNION arms, whose keys share one tree.
		// Red-black insertion can recolor at most one grandparent per iteration after the search.
		long perRow = 5L + height / 2L + 3L * (replayWidth + 1L) + (long) keyWidth * (height + 2L);
		long rows = saturatedMultiply(entries, perRow);
		return new SweepBound(seeks, rows);
	}

	private record SweepBound(long seeks, long rows) {
		long work() {
			return saturatedAdd(rows, saturatedMultiply(seeks, RuntimeBuildAdmission.SEEK_WORK_UNITS));
		}
	}

	private static long saturatedAdd(long left, long right) {
		return left > Long.MAX_VALUE - right ? Long.MAX_VALUE : left + right;
	}

	private static long saturatedMultiply(long left, long right) {
		return left != 0L && right > Long.MAX_VALUE / left ? Long.MAX_VALUE : left * right;
	}

	private static int compareKeys(GroupKey left, GroupKey right) {
		for (int i = 0; i < left.ids.length; i++) {
			int order = Long.compare(left.ids[i], right.ids[i]);
			if (order != 0) {
				return order;
			}
		}
		return 0;
	}

	private static RowCursor openSweep(SlotPlan plan, RowState row) throws IOException {
		if (plan instanceof UnionPlan union) {
			return new SweepUnion(union, row);
		}
		return ((PatternPlan) plan).open(row);
	}

	private static final class SweepUnion implements FactorizedRowCursor {
		private final SlotPlan right;
		private final RowState row;
		private RowCursor current;
		private boolean rightOpened;

		SweepUnion(UnionPlan plan, RowState row) throws IOException {
			this.right = plan.right;
			this.row = row;
			this.current = openSweep(plan.left, row);
		}

		@Override
		public boolean next() throws IOException {
			if (current.next()) {
				return true;
			}
			if (!rightOpened) {
				current.close();
				current = openSweep(right, row);
				rightOpened = true;
				return current.next();
			}
			return false;
		}

		@Override
		public long multiplicity() {
			return weight(current);
		}

		@Override
		public void close() {
			current.close();
		}
	}

	private static final class ProbeMeasurement implements NativeLmdbQuerySource.AdjacencyAccessObserver {
		long seeks;
		long rows;
		long matches;

		@Override
		public void access(boolean used, String reason, StatementOrder order, long s, long p, long o, long c) {
		}

		@Override
		public void measurement(boolean adjacency, long scanned, long matched, long filtered, boolean censored,
				boolean physicalScanCount) {
			if (!adjacency && !censored && physicalScanCount && scanned >= 0L) {
				seeks = saturatedAdd(seeks, 1L);
				rows = saturatedAdd(rows, scanned);
				matches = saturatedAdd(matches, Math.max(0L, matched));
			}
		}
	}

